INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_CITY_7','The Returning Light');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_CITY_8','Keeper''s Anchorage');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_CITY_9','Brasswater');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_CIV','The Lantern Fleet');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_CIV5_HEADING_1','No Harbor Goes Dark');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_CIV5_TEXT_1','The Lantern Fleet began as families crossing restless oceans in search of a peaceful shore. Storms and predatory fleets taught them a common duty: no vessel would be forgotten, no sailor abandoned, no harbor left in darkness.[NEWLINE][NEWLINE]No Harbor Goes Dark checks every owned city once at owner-turn start. The native coastal-city test must pass, and at least one living, non-embarked naval combat unit owned by that city''s actual owner must occupy its exact city-center plot. Adjacent ships, Cargo Ships, civilians, embarked land units and friendly or allied foreign ships do not qualify. Any eligible naval military unit, including later-era warships, works; multiple ships never stack.[NEWLINE][NEWLINE]Each qualifying city receives +2 Science and +1 Culture through an invisible building. The Signal Lighthouse adds +1 permanent Culture and, when present at the same qualifying snapshot, +2 Gold. Combined: +2 Science, +2 Culture, +2 Gold, plus the ordinary Lighthouse effects. These flat base yields have no era scaling and follow ordinary native city yield modifiers.[NEWLINE][NEWLINE]Entering after the check waits until next turn. Leaving after the check retains this turn''s bonus. Save/load retains the existing snapshot without another check or payout. Capture immediately clears both conditional bonuses, including a transfer to another Lantern player; the new owner waits for its next legitimate turn-start check.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_CIV_PEDIA','The Lantern Fleet began as families crossing restless oceans in search of a peaceful shore. Storms and predatory fleets taught them a common duty: no vessel would be forgotten, no sailor abandoned, no harbor left in darkness.[NEWLINE][NEWLINE]No Harbor Goes Dark checks every owned city once at owner-turn start. The native coastal-city test must pass, and at least one living, non-embarked naval combat unit owned by that city''s actual owner must occupy its exact city-center plot. Adjacent ships, Cargo Ships, civilians, embarked land units and friendly or allied foreign ships do not qualify. Any eligible naval military unit, including later-era warships, works; multiple ships never stack.[NEWLINE][NEWLINE]Each qualifying city receives +2 Science and +1 Culture through an invisible building. The Signal Lighthouse adds +1 permanent Culture and, when present at the same qualifying snapshot, +2 Gold. Combined: +2 Science, +2 Culture, +2 Gold, plus the ordinary Lighthouse effects. These flat base yields have no era scaling and follow ordinary native city yield modifiers.[NEWLINE][NEWLINE]Entering after the check waits until next turn. Leaving after the check retains this turn''s bonus. Save/load retains the existing snapshot without another check or payout. Capture immediately clears both conditional bonuses, including a transfer to another Lantern player; the new owner waits for its next legitimate turn-start check.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_DAWN','High Keeper Maren, Guardian of the Eternal Flame, your people await your guidance.[NEWLINE][NEWLINE]For generations, your ancestors crossed the restless oceans, searching for shores where their families could finally find peace.[NEWLINE][NEWLINE]They endured terrible storms, treacherous waters, and the cruelty of those who preyed upon defenseless travelers.[NEWLINE][NEWLINE]Yet through every hardship, one promise endured.[NEWLINE][NEWLINE]No vessel would be forgotten. No sailor would be abandoned. No harbor would be left in darkness.[NEWLINE][NEWLINE]Now, your people have established their first permanent settlement.[NEWLINE][NEWLINE]Raise your lighthouses. Gather your fleets. Let your lanterns illuminate the darkest corners of the world.[NEWLINE][NEWLINE]Will you guide your civilization toward a brighter future?');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_DEFEAT_1','The lantern... please... don''t let it go out.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_FRIENDLY_1','Come in, friend. There is warmth by the lantern.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_GOLD','Signal Harbor Trade');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_GOLD_HELP','Internal Signal Lighthouse turn-start snapshot: +2 Gold. Cannot be constructed, purchased or sold.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_GREETING_1','Welcome, traveler. You must have endured quite a journey. Come inside. The storm is growing stronger.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_GUARD','Guarded Harbor');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_GUARD_HELP','Internal turn-start snapshot: +2 Science and +1 Culture. Cannot be constructed, purchased or sold.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_HOSTILE_1','Our keepers are watching your sails.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_LEADER','High Keeper Maren');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_LEADER_PEDIA','High Keeper Maren is an elderly guardian of the sea roads. In a weathered navy coat bearing golden insignia, she carries a large brass lantern through a chamber overlooking the stormy ocean. Protective, cautious and hospitable, she values safe navigation and defensive naval strength. Threats against her harbors meet a determined response.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_LIGHTHOUSE','Signal Lighthouse');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_LIGHTHOUSE_HELP','Replaces the active Lighthouse and retains all its normal effects. Always provides +1 [ICON_CULTURE] Culture. Provides +2 [ICON_GOLD] Gold for an owner-turn if this city has a Signal Lighthouse and qualifies as a Guarded Harbor at that turn''s start. Requires an owned naval combat unit inside the coastal CITY CENTER. One ship is enough; movement afterward does not change the snapshot. No era scaling.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_LIGHTHOUSE_PEDIA','Signal Lighthouses preserve the promise that no harbor will be left in darkness. Their keepers record safe passages, welcome returning families and coordinate the ships sheltering beneath their lights. Their +1 Culture needs no ship. Their +2 Gold requires both the Lighthouse and Guarded Harbor qualification at owner-turn start. It shares the same fixed snapshot as No Harbor Goes Dark and adds to all ordinary Lighthouse effects.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_LIGHTHOUSE_STRATEGY','Build for its normal Lighthouse benefits and permanent Culture. Station an owned warship in the coastal city center before turn start for the additional Gold. With a qualifying guard, this building and the ability together add +2 Science, +2 Culture and +2 Gold.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_MAREN_HEADING_1','The Keeper''s Promise');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_MAREN_LIVED','The age of the returning fleets');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_MAREN_NAME','High Keeper Maren');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_MAREN_SUBTITLE','Guardian of the Eternal Flame');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_MAREN_TEXT_1','High Keeper Maren is an elderly guardian of the sea roads. In a weathered navy coat bearing golden insignia, she carries a large brass lantern through a chamber overlooking the stormy ocean. Protective, cautious and hospitable, she values safe navigation and defensive naval strength. Threats against her harbors meet a determined response.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_MAREN_TITLES_1','High Keeper of the Lantern Fleet');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_NEUTRAL_1','What news do you bring from the sea?');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_PEACE_1','Let the lights welcome our sailors home.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_PEACE_OFFER_1','There is still a safe harbor for peace.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_PROMOTION','Keeper of Friendly Waters');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_PROMOTION_HELP','+1 Sight. +15% Combat Strength in friendly territory on attack and defense. No bonus Strength elsewhere. Retained on upgrade; granted only to Beacon Cutters.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_SHORT','The Lantern Fleet');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_SPY_1','Wick');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_SPY_10','Last Lantern');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_SPY_2','Harbor Watch');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_SPY_3','Sea Glass');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_SPY_4','North Light');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_SPY_5','Fog Bell');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_SPY_6','Brass Key');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_SPY_7','Storm Petrel');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_SPY_8','Blue Flame');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_SPY_9','Night Tide');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_STRATEGY','Defensive naval economy. Settle the coast, keep owned naval combat ships inside city centers before turn start and develop Signal Lighthouses. Science and Culture are preferred victories. A guard protects the harbor and powers a fixed economic snapshot; leaving afterward keeps the bonus until the next check.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_TRADE_1','May this agreement bring our people safely home.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_TRAIT','No Harbor Goes Dark');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_TRAIT_HELP','At the start of your turn, each coastal city with at least one of its owner''s naval combat units inside the CITY CENTER gains +2 [ICON_RESEARCH] Science and +1 [ICON_CULTURE] Culture for that turn. One ship is enough; additional ships do not stack. Adjacent, foreign, civilian and embarked units do not qualify. Movement after the check changes eligibility only at your next turn start. No era scaling.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_UNIT','Beacon Cutter');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_UNIT_HELP','Replaces the active Trireme. Retains its normal rules, stats, requirements and upgrade path. +1 Sight and +15% Combat Strength when fighting in friendly territory, on attack and defense. No additional Strength elsewhere. These unique bonuses are retained on upgrade.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_UNIT_PEDIA','Beacon Cutters escort travelers through the dangerous approaches to Lantern ports. Their crews carry powerful lanterns and know the friendly shoals intimately. Their hulls and armaments follow the ordinary Trireme tradition. The unique lantern training grants +1 Sight and +15% Strength in native friendly territory, on offense and defense, and is retained on upgrade; ordinary inherited promotions follow their normal rules.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_UNIT_STRATEGY','Scout the coast with additional Sight, protect friendly waters and station a Cutter inside a coastal city center before your next turn begins. Any later naval combat unit can also guard a harbor.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_LANTERN_WAR_1','I offered your people safe harbor. You answered with violence. Very well. Our lights shall guide our ships to yours.');
